/* Ventas e ingresos: periodo y acumulados                            */
/* ------------------------------------------------------------------ */

#salesRange { width: auto; min-width: 156px; }

.date-filter {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12.5px;
  font-weight: 550;
  color: var(--ink-3);
}
.date-filter input[type="date"] {
  width: auto;
  min-width: 134px;
  padding: 8px 10px;
  font-size: 13px;
}

.two-col > .card { min-width: 0; }
.two-col table.data .cat-track { max-width: 220px; }

@media (max-width: 620px) {
  #salesRange { width: 100%; }
  .date-filter { flex: 1 1 100%; }
  .date-filter input[type="date"] { flex: 1 1 auto; min-width: 0; width: 100%; }
}
